export default function Panel(): React.JSX.Element {
  const { locale, t } = useI18n()
  const [settings, setSettings] = useState<AppSettings>(structuredClone(defaultSettings)); const [saved, setSaved] = useState<AppSettings>(structuredClone(defaultSettings))
  const [page, setPage] = useState<Page>('environment'); const [search, setSearch] = useState(''); const [message, setMessage] = useState(''); const [loading, setLoading] = useState(true)
  const [profileName, setProfileName] = useState('Default')
  const [profileInstruction, setProfileInstruction] = useState('SELECT')
  const [profileSample, setProfileSample] = useState("select customer_id, sum(total) as amount from orders where state = 'paid' group by customer_id;")
  const dirty = JSON.stringify(settings) !== JSON.stringify(saved)
  const pages = useMemo(() => FieldPages.map((item) => ({ ...item, fields: item.fields.filter((field) => `${item.group} ${item.title} ${field.label} ${field.description ?? ''}`.toLowerCase().includes(search.toLowerCase())) })).filter((item) => !search || item.fields.length || `${item.group} ${item.title}`.toLowerCase().includes(search.toLowerCase())), [search])
  useEffect(() => { let active = true; void window.tuxsql.loadSettings().then((result) => { if (!active) return; setSettings(result.settings); setSaved(result.settings); setProfileName(result.settings.editor.activeFormatProfile); if (result.warning) setMessage(result.warning) }).catch((error: unknown) => setMessage(errorMessage(error))).finally(() => { if (active) setLoading(false) }); return () => { active = false } }, [])

  function value(path: string): unknown { return path.split('.').reduce<unknown>((item, key) => item && typeof item === 'object' ? (item as Record<string, unknown>)[key] : undefined, settings) }
  function setValue(path: string, next: unknown): void { setSettings((current) => { const copy = structuredClone(current) as unknown as Record<string, unknown>; const parts = path.split('.'); let node = copy; for (const part of parts.slice(0, -1)) node = node[part] as Record<string, unknown>; node[parts.at(-1)!] = next; return copy as unknown as AppSettings }) }
  async function apply(close = false): Promise<void> { setMessage(settings.language.locale === 'pt-BR' ? 'Salvando configurações…' : t('opt.saving')); try { const next = await window.tuxsql.saveSettings(settings); setSettings(next); setSaved(next); window.dispatchEvent(new CustomEvent('tuxsql:settings-changed', { detail: next })); setMessage(next.language.locale === 'pt-BR' ? 'Alterações aplicadas.' : 'Changes applied.'); if (close) window.dispatchEvent(new Event('tuxsql:close-panel')) } catch (error) { setMessage(errorMessage(error)) } }
  async function resetPage(): Promise<void> { if (!window.confirm(t('opt.resetPage.confirm'))) return; const selectedPage = FieldPages.find((item) => item.id === page); if (!selectedPage) return; if (page === 'shortcuts') { setSettings((current) => ({ ...current, shortcuts: structuredClone(defaultSettings.shortcuts) })); return } if (page === 'editor.aliases') { setValue('editor.aliasRules', structuredClone(defaultSettings.editor.aliasRules)); return } if (page === 'editor.profiles') { setSettings((current) => ({ ...current, editor: { ...current.editor, activeFormatProfile: defaultSettings.editor.activeFormatProfile, formatProfiles: [] } })); setProfileName(defaultSettings.editor.activeFormatProfile); return } for (const field of selectedPage.fields) setValue(field.path, field.path.split('.').reduce<unknown>((item, key) => item && typeof item === 'object' ? (item as Record<string, unknown>)[key] : undefined, defaultSettings)) }
  async function resetAll(): Promise<void> { if (!window.confirm(t('opt.resetAll.confirm'))) return; const next = await window.tuxsql.resetSettings(); setSettings(next); setSaved(next); window.dispatchEvent(new CustomEvent('tuxsql:settings-changed', { detail: next })); setMessage(t('opt.applied')) }
  async function importConfig(): Promise<void> { try { const next = await window.tuxsql.importSettings(); if (next) { setSettings(next); setSaved(next); window.dispatchEvent(new CustomEvent('tuxsql:settings-changed', { detail: next })); setMessage(t('opt.imported')) } } catch (error) { setMessage(errorMessage(error)) } }
  async function exportConfig(): Promise<void> { try { const path = await window.tuxsql.exportSettings(settings); setMessage(path ? t('opt.exported', [path]) : '') } catch (error) { setMessage(errorMessage(error)) } }
  async function checkForUpdates(): Promise<void> { try { const result = await window.tuxsql.updaterCheck(); setMessage(result.message ?? (result.newVersion ? t('updates.available', [result.newVersion]) : t('updates.upToDate'))) } catch (error) { setMessage(errorMessage(error)) } }
  function captureBinding(index: number, event: React.KeyboardEvent<HTMLInputElement>): void {
    event.preventDefault(); const parts: string[] = []; if (event.ctrlKey || event.metaKey) parts.push('Ctrl'); if (event.altKey) parts.push('Alt'); if (event.shiftKey) parts.push('Shift'); if (!['Control', 'Alt', 'Shift', 'Meta'].includes(event.key)) parts.push(event.key.length === 1 ? event.key.toUpperCase() : event.key); else return
    const shortcut = parts.join('+'); const candidate = settings.shortcuts.bindings.map((binding, i) => i === index ? { ...binding, shortcut } : binding); const collision = findKeymapConflicts(candidate).find((item) => item.commands.includes(settings.shortcuts.bindings[index].command))
    if (collision) { if (!window.confirm(`${shortcut} conflicts with ${collision.commands.filter((command) => command !== settings.shortcuts.bindings[index].command).join(', ')}. Reassign?`)) return; setSettings((current) => { const bindings = [...current.shortcuts.bindings]; for (const item of bindings) if (item.command !== bindings[index].command && normalizeShortcut(item.shortcut) === normalizeShortcut(shortcut)) item.shortcut = ''; bindings[index] = { ...bindings[index], shortcut }; return { ...current, shortcuts: { ...current.shortcuts, bindings } } }); return }
    setSettings((current) => { const bindings = [...current.shortcuts.bindings]; bindings[index] = { ...bindings[index], shortcut }; return { ...current, shortcuts: { ...current.shortcuts, bindings } } })
  }
  const current = FieldPages.find((item) => item.id === page) ?? FieldPages[0]!
  const activeProfile = (settings.editor.formatProfiles.find((profile) => profile.name === profileName) ?? builtInFormatProfiles.find((profile) => profile.name === profileName) ?? builtInFormatProfiles[3]!) as SqlFormatProfile
  const profilePreview = formatSql(profileSample, { profile: activeProfile })
  const previewStyle = { background: settings.appearance.theme === 'dark' || settings.appearance.theme === 'high-contrast' ? '#27292d' : '#fff', color: settings.appearance.theme === 'dark' || settings.appearance.theme === 'high-contrast' ? '#f2f3f5' : '#1f2328', fontFamily: settings.editor.fontName, fontSize: settings.editor.fontSize, borderColor: settings.appearance.accent }

  const pageTitle = (id: Page, fallback: string): string => locale === 'pt-BR' ? ({ environment: 'Geral', 'shortcuts': 'Teclado', output: 'Saída', 'environment.categories': 'Categorias', appearance: 'Fontes e cores', 'environment.tabs': 'Guias e janelas', 'environment.projects': 'Projetos', smtp: 'SMTP', 'documents.sql': 'Documentos SQL e editores', 'documents.restore': 'Restauração e histórico', notifications: 'Notificações', editor: 'Geral', 'editor.completion': 'Conclusão de código', 'editor.aliases': 'Regras de alias', 'editor.formatting': 'Formatação', 'editor.profiles': 'Perfis de formatação', execution: 'Saída', grid: 'Geral', connections: 'Conexões', databaseExplorer: 'Geral', language: 'Idioma', queryBuilder: 'Geral', dataComparison: 'Geral' }[id] ?? fallback) : fallback
  const groupTitle = (value: string): string => locale === 'pt-BR' ? ({ Environment: 'Ambiente', 'AI Assistant': 'Assistente de IA', 'Schema Comparison': 'Comparação de esquemas', 'Text Editor': 'Editor de texto', 'Data Comparison': 'Comparação de dados', 'Data Editor': 'Editor de dados', 'Data Export': 'Exportação de dados', 'Data Generation': 'Geração de dados', 'Database Explorer': 'Explorador de banco de dados', 'Query Builder': 'Construtor de consultas', 'Database Diagram': 'Diagrama de banco de dados', 'Source Control': 'Controle de versão', Debugging: 'Depuração', 'Master-Detail': 'Mestre-detalhe', 'Query Profiler': 'Perfilador de consultas' }[value] ?? value) : value
  const pageModified = (item: typeof FieldPages[number]): boolean => item.fields.some((field) => JSON.stringify(value(field.path)) !== JSON.stringify(field.path.split('.').reduce<unknown>((node, key) => node && typeof node === 'object' ? (node as Record<string, unknown>)[key] : undefined, defaultSettings))) || (item.id === 'shortcuts' && JSON.stringify(settings.shortcuts) !== JSON.stringify(defaultSettings.shortcuts))
  function updateAliasRule(index: number, update: Partial<AppSettings['editor']['aliasRules'][number]>): void { setSettings((currentSettings) => ({ ...currentSettings, editor: { ...currentSettings.editor, aliasRules: currentSettings.editor.aliasRules.map((rule, i) => i === index ? { ...rule, ...update } : rule) } })) }
  function updateProfile(update: Partial<SqlFormatProfile>): void { setSettings((currentSettings) => { const exists = currentSettings.editor.formatProfiles.some((profile) => profile.name === profileName); return { ...currentSettings, editor: { ...currentSettings.editor, formatProfiles: exists ? currentSettings.editor.formatProfiles.map((profile) => profile.name === profileName ? { ...profile, ...update } : profile) : [...currentSettings.editor.formatProfiles, { ...activeProfile, ...update }] } } }) }
  function createProfile(): void { const name = window.prompt(locale === 'pt-BR' ? 'Nome do novo perfil' : 'New profile name'); if (!name?.trim()) return; const created = { ...activeProfile, name: name.trim() }; setSettings((currentSettings) => ({ ...currentSettings, editor: { ...currentSettings.editor, formatProfiles: [...currentSettings.editor.formatProfiles.filter((profile) => profile.name !== created.name), created], activeFormatProfile: created.name } })); setProfileName(created.name) }
  function addExistingProfile(name: string): void { const profile = builtInFormatProfiles.find((item) => item.name === name); if (!profile || settings.editor.formatProfiles.some((item) => item.name === name)) return; setSettings((currentSettings) => ({ ...currentSettings, editor: { ...currentSettings.editor, formatProfiles: [...currentSettings.editor.formatProfiles, structuredClone(profile)] } })); setProfileName(name) }
  return <section className="tool-panel options-panel" aria-label={locale === 'pt-BR' ? 'Opções' : 'Options...'}>
    <header className="options-header"><div><h2>{t('opt.title')}</h2><p>{locale === 'pt-BR' ? 'Configurações de inicialização e esquema de atalhos ativo.' : 'Environment startup settings and active keyboard mapping scheme.'}</p></div><button type="button" onClick={() => void importConfig()}>{t('opt.importExport')}</button><button type="button" onClick={() => void exportConfig()}>{locale === 'pt-BR' ? 'Exportar…' : 'Export…'}</button></header>
    {message && <p role="status" className="options-message">{message}</p>}
    {loading ? <p>{locale === 'pt-BR' ? 'Carregando configurações…' : 'Loading settings…'}</p> : <div className="options-layout">
      <aside className="options-sidebar"><label>{locale === 'pt-BR' ? 'Buscar opções…' : 'Search options…'}<input value={search} onChange={(event) => setSearch(event.target.value)} placeholder={locale === 'pt-BR' ? 'Buscar opções…' : 'Search options…'} /></label><nav>{[...new Set(pages.map((item) => item.group))].map((group) => <section className="options-tree-group" key={group}><strong>{groupTitle(group)}</strong>{pages.filter((item) => item.group === group).map((item) => <button key={item.id} className={item.id === page ? 'selected' : ''} onClick={() => setPage(item.id)}>{pageTitle(item.id, item.title)}{pageModified(item) && <span aria-label={locale === 'pt-BR' ? 'modificado' : 'modified'}> •</span>}</button>)}</section>)}{search && !pages.length && <p>{locale === 'pt-BR' ? 'Nada encontrado' : 'Nothing found'}</p>}</nav></aside>
      <main className="options-page"><div className="options-breadcrumb">{groupTitle(current.group)} › {pageTitle(current.id, current.title)}</div><h3>{pageTitle(page, current.title)}</h3><p className="options-hint">{locale === 'pt-BR' ? 'Passe o cursor sobre uma opção para ver sua descrição detalhada.' : 'Move the mouse cursor to the option to obtain its detailed description.'}</p>{page === 'environment' && <button type="button" onClick={() => void checkForUpdates()}>{t('updates.checkNow')}</button>}
        {page === 'environment.categories' ? <section className="environment-category-reference"><p>{locale === 'pt-BR' ? 'A categoria, cor e forma são configuradas individualmente nas propriedades de cada conexão.' : 'Set the category, color, and shape on each connection’s properties.'}</p><ul>{(['dev', 'prod', 'sandbox', 'test'] as const).map((category) => <li key={category}><span data-shape={({ dev: 'square', test: 'diamond', prod: 'circle', sandbox: 'triangle' } as const)[category]} className="environment-badge" style={{ '--environment-color': ({ dev: '#2e7d32', test: '#ed6c02', prod: '#c62828', sandbox: '#1565c0' } as const)[category] } as React.CSSProperties}>{t(`conn.environment.${category}`)}</span></li>)}<li>{locale === 'pt-BR' ? 'Sem categoria: sem indicador' : 'No category: no indicator'}</li></ul></section> : page !== 'shortcuts' ? current.fields.length ? <div className="options-fields">{current.fields.map((field) => <OptionField key={field.path} field={field} locale={locale} value={value(field.path)} changed={JSON.stringify(value(field.path)) !== JSON.stringify(field.path.split('.').reduce<unknown>((item, key) => item && typeof item === 'object' ? (item as Record<string, unknown>)[key] : undefined, defaultSettings))} onChange={(next) => { setValue(field.path, next); if (field.path === 'editor.activeFormatProfile') setProfileName(String(next)) }} onReset={() => setValue(field.path, field.path.split('.').reduce<unknown>((item, key) => item && typeof item === 'object' ? (item as Record<string, unknown>)[key] : undefined, defaultSettings))} />)}</div> : <p>{locale === 'pt-BR' ? 'Não há opções adicionais disponíveis para esta categoria nesta versão.' : 'This category has no additional options in this build.'}</p> : <Shortcuts settings={settings} locale={locale} onCapture={captureBinding} onReset={(index) => setSettings((currentSettings) => { const bindings = [...currentSettings.shortcuts.bindings]; bindings[index] = { ...defaultSettings.shortcuts.bindings[index] }; return { ...currentSettings, shortcuts: { ...currentSettings.shortcuts, bindings } } })} onScheme={(scheme) => setValue('shortcuts.scheme', scheme)} onAdd={() => setSettings((currentSettings) => ({ ...currentSettings, shortcuts: { ...currentSettings.shortcuts, bindings: [...currentSettings.shortcuts.bindings, { command: 'New command', shortcut: '', context: 'Global' }] } }))} />}
        {page === 'appearance' && <section className="options-preview"><h4>{t('panel.options.mc5346666d8')}</h4><div style={previewStyle}><strong>SELECT</strong> <span>{t('panel.options.meaeb824788')}</span> <em>{t('panel.options.m7f0f47a818')}</em><div className="options-preview-accent" style={{ background: settings.appearance.accent }} /></div></section>}
        {page === 'editor.aliases' && <section className="editor-alias-rules"><p>{locale === 'pt-BR' ? 'Cada máscara escolhe uma regra de alias para tabelas inseridas pela conclusão.' : 'Each mask chooses an alias rule for tables inserted from completion.'}</p><table><thead><tr><th>{locale === 'pt-BR' ? 'Condição / máscara' : 'Condition / mask'}</th><th>{locale === 'pt-BR' ? 'Ação' : 'Action'}</th><th /></tr></thead><tbody>{settings.editor.aliasRules.map((rule, index) => <tr key={`${index}:${rule.condition}`}><td><input aria-label={`Alias rule ${index + 1} condition`} value={rule.condition} onChange={(event) => updateAliasRule(index, { condition: event.target.value })} placeholder="<Sales>.<tbl_*>" /></td><td><select aria-label={`Alias rule ${index + 1} action`} value={rule.action} onChange={(event) => updateAliasRule(index, { action: event.target.value as 'none' | 'short' | 'full' })}><option value="none">{locale === 'pt-BR' ? 'Sem alias' : 'No alias'}</option><option value="short">{locale === 'pt-BR' ? 'Alias curto' : 'Short alias'}</option><option value="full">{locale === 'pt-BR' ? 'Nome completo' : 'Full name'}</option></select></td><td><button type="button" onClick={() => setSettings((currentSettings) => ({ ...currentSettings, editor: { ...currentSettings.editor, aliasRules: currentSettings.editor.aliasRules.filter((_item, i) => i !== index) } }))}>{locale === 'pt-BR' ? 'Remover' : 'Remove'}</button></td></tr>)}</tbody></table><button type="button" onClick={() => setSettings((currentSettings) => ({ ...currentSettings, editor: { ...currentSettings.editor, aliasRules: [...currentSettings.editor.aliasRules, { condition: '<*>', action: 'short' }] } }))}>{locale === 'pt-BR' ? 'Adicionar regra' : 'Add rule'}</button></section>}
        {page === 'editor.profiles' && <section className="editor-format-profiles"><div className="options-fields"><label className="options-field"><span>{locale === 'pt-BR' ? 'Perfil' : 'Profile'}</span><select value={profileName} onChange={(event) => setProfileName(event.target.value)}>{[...new Set([...formatProfileNames, ...settings.editor.formatProfiles.map((profile) => profile.name)])].map((name) => <option key={name}>{name}</option>)}</select></label></div><div className="options-profile-actions"><button type="button" onClick={createProfile}>{locale === 'pt-BR' ? 'Criar novo' : 'Create New'}</button><select aria-label={locale === 'pt-BR' ? 'Adicionar perfil existente' : 'Add Existing profile'} defaultValue="" onChange={(event) => { if (event.target.value) addExistingProfile(event.target.value); event.currentTarget.value = '' }}><option value="">{locale === 'pt-BR' ? 'Adicionar existente…' : 'Add Existing…'}</option>{builtInFormatProfiles.filter((profile) => !settings.editor.formatProfiles.some((item) => item.name === profile.name)).map((profile) => <option key={profile.name}>{profile.name}</option>)}</select><button type="button" onClick={() => setProfileName(profileName)}>{locale === 'pt-BR' ? 'Abrir selecionado' : 'Open Selected'}</button><button type="button" onClick={() => setSettings((currentSettings) => ({ ...currentSettings, editor: { ...currentSettings.editor, activeFormatProfile: profileName } }))}>{locale === 'pt-BR' ? 'Definir como ativo' : 'Set as Active'}</button></div><h4>{locale === 'pt-BR' ? `Regras do perfil: ${profileName}` : `Profile rules: ${profileName}`}</h4><label className="options-field"><span>{locale === 'pt-BR' ? 'Instrução SQL' : 'SQL instruction'}</span><select value={profileInstruction} onChange={(event) => setProfileInstruction(event.target.value)}>{['CALL', 'CASE', 'CREATE TABLE', 'CREATE TRIGGER', 'CREATE VIEW', 'DECLARE', 'DELETE', 'INSERT', 'SELECT'].map((name) => <option key={name}>{name}</option>)}</select></label><div className="options-fields">{([['breakBeforeParentheses', 'Break before parentheses'], ['indentParameterLists', 'Indent parameter lists'], ['stackParameterLists', 'Stack parameter lists']] as const).map(([key, label]) => <label className="options-field" key={key}><span>{label}</span><input type="checkbox" checked={activeProfile.instructionRules?.[profileInstruction]?.[key] ?? activeProfile[key]} onChange={(event) => updateProfile({ instructionRules: { ...activeProfile.instructionRules, [profileInstruction]: { ...activeProfile.instructionRules?.[profileInstruction], [key]: event.target.checked } } })} /></label>)}{([['nestedIndent', 'Indent nested blocks']] as const).map(([key, label]) => <label className="options-field" key={key}><span>{label}</span><input type="checkbox" checked={activeProfile[key]} onChange={(event) => updateProfile({ [key]: event.target.checked })} /></label>)}</div><label className="options-profile-sample"><span>{locale === 'pt-BR' ? 'Instrução de amostra' : 'Sample statement'}</span><textarea value={profileSample} onChange={(event) => setProfileSample(event.target.value)} rows={5} spellCheck={false} /></label><pre className="options-format-preview" aria-live="polite">{profilePreview}</pre><p>{locale === 'pt-BR' ? 'A amostra formatada é atualizada enquanto você edita.' : 'The formatted sample updates as you edit.'}</p></section>}
      </main>
    </div>}
    <footer className="options-footer"><div><button type="button" onClick={() => void resetPage()}>{t('opt.resetPage')}</button><button type="button" onClick={() => void resetAll()}>{t('opt.resetAll')}</button></div><div><button type="button" onClick={() => { if (!dirty || window.confirm(locale === 'pt-BR' ? 'Descartar alterações não salvas?' : 'Discard unsaved settings changes?')) window.dispatchEvent(new Event('tuxsql:close-panel')) }}>{t('common.cancel')}</button><button type="button" disabled={!dirty} onClick={() => void apply()}>{t('common.apply')}</button><button type="button" className="button-primary" disabled={!dirty} onClick={() => void apply(true)}>{t('common.ok')}</button></div></footer>
  </section>
}

