function OptionField({ field, locale, value, changed, onChange, onReset }: { field: Field; locale: 'en' | 'pt-BR'; value: unknown; changed: boolean; onChange(value: unknown): void; onReset(): void }): React.JSX.Element {
  const warningParts = /^execution\.warningCategories\.(none|dev|test|prod|sandbox|custom)\.(truncate|delete|update)$/.exec(field.path)
  const warningLabels: Record<string, string> = { none: 'Sem categoria', dev: 'Desenvolvimento', test: 'Teste', prod: 'Produção', sandbox: 'Ambiente isolado', custom: 'Personalizado', truncate: 'TRUNCATE', delete: 'DELETE', update: 'UPDATE' }
  const label = locale === 'pt-BR' ? warningParts ? `${warningLabels[warningParts[1]!]!} · aviso ${warningLabels[warningParts[2]!]!}` : ptFieldLabels[field.path] ?? field.label : field.label
  return <label className="options-field"><span>{label}{field.description && <small>{field.description}</small>}</span>{field.type === 'checkbox' ? <input type="checkbox" checked={Boolean(value)} onChange={(event) => onChange(event.target.checked)} /> : field.type === 'select' ? <select value={String(value)} onChange={(event) => onChange(event.target.value)}>{field.choices?.map((item) => <option key={item} value={item}>{locale === 'pt-BR' ? ({system:'Sistema',en:'Inglês', 'pt-BR':'Português (Brasil)',auto:'Automático',dev:'Desenvolvimento',release:'Versão estável',startup:'A cada abertura',daily:'Diariamente',light:'Claro',dark:'Escuro','high-contrast':'Alto contraste',compact:'Compacta',comfortable:'Confortável',upper:'Maiúsculas',lower:'Minúsculas','as-typed':'Como digitado',stop:'Parar',ask:'Perguntar',continue:'Continuar','start-page':'Página inicial','last-workspace':'Último espaço de trabalho',empty:'Vazio',iso:'ISO','select-data':'Selecionar dados','object-editor':'Editor do objeto','data-editor':'Editor de dados',execute:'Executar',all:'Todas as linhas',first:'Primeiras linhas',none:'Nenhum',split:'Dividido',combined:'Combinado',block:'Bloco',smart:'Inteligente',prefix:'Prefixo',substring:'Trecho',camelCase:'Camel case',object:'Objeto','schema-object':'Esquema e objeto',always:'Sempre',reserved:'Palavras reservadas',needed:'Quando necessário'}[item] ?? item) : item}</option>)}</select> : <input type={field.type ?? 'text'} min={field.min} max={field.max} step={field.step} value={String(value ?? '')} onChange={(event) => onChange(field.type === 'number' ? Number(event.target.value) : event.target.value)} />}{changed && <button type="button" title={locale === 'pt-BR' ? 'Restaurar padrão' : 'Reset to Default'} onClick={onReset}>↺</button>}</label>
}

function Shortcuts({ settings, locale, onCapture, onReset, onScheme, onAdd }: { settings: AppSettings; locale: 'en' | 'pt-BR'; onCapture(index: number, event: React.KeyboardEvent<HTMLInputElement>): void; onReset(index: number): void; onScheme(value: string): void; onAdd(): void }): React.JSX.Element {
  const pt = locale === 'pt-BR'
  return <><label className="options-scheme">{pt ? 'Aplicar o seguinte esquema adicional de teclado:' : 'Apply the following additional keyboard mapping scheme:'}<select value={settings.shortcuts.scheme} onChange={(event) => onScheme(event.target.value)}>{['default', 'dbeaver', 'ssms', 'vscode'].map((item) => <option key={item}>{item}</option>)}</select></label><div className="options-shortcuts"><table><thead><tr><th>{pt ? 'Comando' : 'Command'}</th><th>{pt ? 'Atalho(s)' : 'Shortcut(s)'}</th><th>{pt ? 'Contexto' : 'Context'}</th><th>{pt ? 'Origem' : 'Source'}</th><th /></tr></thead><tbody>{settings.shortcuts.bindings.map((binding: KeyBinding, index) => <tr key={`${binding.command}-${index}`}><td>{binding.command}</td><td><input aria-label={`${pt ? 'Atalho para' : 'Shortcut for'} ${binding.command}`} placeholder={pt ? 'Pressione as teclas…' : 'Press keys…'} value={binding.shortcut} onKeyDown={(event) => onCapture(index, event)} onChange={() => undefined} /></td><td>{binding.context === 'Global' ? (pt ? 'Global' : 'Global') : binding.context === 'Editor' && pt ? 'Editor' : binding.context === 'Debugger' && pt ? 'Depurador' : binding.context}</td><td>{JSON.stringify(binding) === JSON.stringify(defaultSettings.shortcuts.bindings[index]) ? (pt ? 'Padrão' : 'Default') : (pt ? 'Personalizado' : 'User')}</td><td><button type="button" onClick={() => onReset(index)}>{pt ? 'Restaurar atalho' : 'Reset Mapping'}</button></td></tr>)}</tbody></table></div><button type="button" onClick={onAdd}>{pt ? 'Adicionar atalho' : 'Add mapping'}</button></>
}

function errorMessage(error: unknown): string { return error instanceof Error ? error.message : 'Settings operation failed.' }
